/* ========== Streak / companion ========== */
function todayStr(){ return new Date().toISOString().slice(0,10); }
function updateStreakOnPlay(streak){
  const today=todayStr();
  if(streak.lastPlayedStr===today)return streak;
  let count;
  if(!streak.lastPlayedStr)count=1;
  else{ const last=new Date(streak.lastPlayedStr+'T00:00:00Z');const now=new Date(today+'T00:00:00Z');
    const d=Math.round((now-last)/86400000);count=d===1?streak.count+1:1; }
  return {lastPlayedStr:today,count,longest:Math.max(streak.longest||0,count)};
}
function stageForStreak(s){
  if(s>=30)return{name:'Ancient Tree',emoji:'🌳'};
  if(s>=14)return{name:'Young Tree',emoji:'🌲'};
  if(s>=7)return{name:'Sapling',emoji:'🌿'};
  if(s>=3)return{name:'Sprout',emoji:'🌾'};
  return{name:'Seed',emoji:'🌱'};
}

