function applyUiMode(){
  document.documentElement.setAttribute('data-mode',uiMode);
  $('dayModeBtn').classList.toggle('active',uiMode==='day');
  $('nightModeBtn').classList.toggle('active',uiMode==='night');
  const root=document.documentElement;
  ['--bg','--bg-deep','--bg-deep-2','--gold','--moss','--same','--sel','--peer'].forEach(v=>root.style.removeProperty(v));

  const hero=$('heroBand');
  const gtopbar=$('gtopbar');
  let pattern='';
  // Themes only colorize Day mode. Night mode always stays neutral black, regardless of chosen theme.
  if(uiMode==='day'){
    const active=themeById(reward.activeTheme) || themeById('forest');
    if(active && active.vars){
      for(const k in active.vars) root.style.setProperty(k,active.vars[k]);
    }
    if(active && active.kind==='design' && active.pattern) pattern=active.pattern;
  }
  if(hero){ if(pattern) hero.setAttribute('data-pattern',pattern); else hero.removeAttribute('data-pattern'); }
  if(gtopbar){ if(pattern) gtopbar.setAttribute('data-pattern',pattern); else gtopbar.removeAttribute('data-pattern'); }
}
function selectQuickTheme(id){
  const t=themeById(id);
  if(!t) return;
  if(themeOwned(reward,id)){
    reward.activeTheme=id;lsSet("sg_reward",reward);applyUiMode();renderColorThemeRow();
    return;
  }
  // not owned: attempt purchase right from the quick row
  if(reward.coins>=t.cost){
    reward.coins-=t.cost;reward.ownedThemes.push(id);reward.activeTheme=id;lsSet("sg_reward",reward);
    Audio2.play('reward');showToast(t.name+' unlocked for '+t.cost+' coins!');
    applyUiMode();renderColorThemeRow();
  }else{
    showToast('Not enough coins yet. Clear levels to earn more, then come back for '+t.name+'.');
  }
}
function renderColorThemeRow(){
  const row=$('colorThemeRow');row.innerHTML='';
  // 3 free colors, plus one paid quick-pick (terracotta) shown with its price if not owned
  const quickIds=['forest','slate','plum','terracotta'];
  quickIds.forEach(function(id){
    const t=themeById(id);if(!t)return;
    const owned=themeOwned(reward,id);
    const sw=document.createElement('div');
    sw.className='color-swatch'+(reward.activeTheme===id?' selected':'');
    sw.style.background=t.swatch;
    sw.title=owned?t.name:(t.name+', '+t.cost+' coins');
    if(!owned){
      const lock=document.createElement('div');
      lock.style.cssText='position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:0.7rem;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,0.5);';
      lock.textContent='🔒';
      sw.style.position='relative';
      sw.appendChild(lock);
    }
    sw.addEventListener('click',function(){ selectQuickTheme(id); });
    row.appendChild(sw);
  });
}

