function renderThemeGrid(containerId, list){
  const grid=$(containerId);grid.innerHTML='';
  list.forEach(function(t){
    const owned=themeOwned(reward,t.id);
    const active=reward.activeTheme===t.id;
    const card=document.createElement('div');
    card.className='theme-card'+(active?' active':'');
    const preview=document.createElement('div');
    preview.className='tc-preview';
    preview.style.background=t.vars?('linear-gradient(135deg,'+t.swatch+',#00000030)'):('linear-gradient(135deg,'+t.swatch+',#00000020)');
    if(t.kind==='design'){ const tag=document.createElement('span');tag.className='design-badge';tag.textContent='✨ Design';preview.appendChild(tag); }
    card.appendChild(preview);
    const name=document.createElement('div');name.className='tc-name';name.textContent=t.name;card.appendChild(name);
    const tag2=document.createElement('div');tag2.className='tc-tag';
    tag2.textContent = t.kind==='free' ? 'Free' : (t.kind==='design' ? 'Design theme' : 'Color theme');
    card.appendChild(tag2);
    const btn=document.createElement('button');btn.className='tc-btn';
    if(active){ btn.textContent='✓ Active'; btn.disabled=true; }
    else if(owned){ btn.classList.add('owned'); btn.textContent='Use'; }
    else{ btn.textContent='🪙 '+t.cost; btn.disabled=reward.coins<t.cost; }
    btn.addEventListener('click',function(){
      if(active) return;
      if(owned){ reward.activeTheme=t.id;lsSet("sg_reward",reward);applyUiMode();renderColorThemeRow();openThemesPage(); }
      else if(reward.coins>=t.cost){
        reward.coins-=t.cost;reward.ownedThemes.push(t.id);reward.activeTheme=t.id;lsSet("sg_reward",reward);
        Audio2.play('reward');showToast(t.name+' unlocked!');applyUiMode();renderColorThemeRow();openThemesPage();
      }else{
        showToast('Not enough coins yet for '+t.name+'.');
      }
    });
    card.appendChild(btn);
    grid.appendChild(card);
  });
}
